   var bad=[], g=null, p=null, E0=null, M=[], i, k, n, v=null, v1=null, pt, lo, hi, per, lv={}, pr={}, kMS={}, kPause=false, faked=false, oSfx=sfx, own=false, heard=[], r0, S, f, NS=[1,3,6];
